fn check_persisted_state_with_readback(
    &self,
    id: Hash,
    state: &State,
    progress: &mut dyn FnMut() -> Result<()>,
    readback: Option<&mut native_authenticated::PostWriteReadback<'_>>,
) -> Result<()> {
    let record = self.record(id).map_err(Error::local_integrity)?;
    continuity_v1::check_state(state, record.height, &self.settings.app)
        .map_err(|error| Error::from(error).local_integrity())?;
    // The native complete-state commitment may already contain this exact
    // full root. Compare all current State bytes before arithmetic reuse;
    // a miss retains the original root calculation and error order. Actual
    // SQL State, record, account graph and history checks still follow.
    let actual_root = if self.state_backend == StateBackend::AuthenticatedV1 {
        self.authenticated_arithmetic
            .state_root(&self.settings, state)?
    } else {
        self.settings.state_root(state)?
    };
    ensure(actual_root == record.root, "ROOT").map_err(Error::local_integrity)?;
    if self.state_backend == StateBackend::AuthenticatedV1 {
        native_authenticated::verify_state_with_readback(
            &self.db,
            &self.settings,
            id,
            state,
            progress,
            Some(&self.authenticated_arithmetic),
            readback,
        )?;
    }
    Ok(())

fn check_active_before_commit_with_readback(
    &self,
    progress: &mut dyn FnMut() -> Result<()>,
    mut readback: Option<&mut native_authenticated::PostWriteReadback<'_>>,
) -> Result<()> {
    progress()?;
    self.namespace()?;
    self.storage_context()?;
    let count: u64 = self
        .db
        .query_row("SELECT COUNT(*) FROM active", [], |row| row.get(0))?;
    ensure(count == 1, "GENERATION").map_err(Error::local_integrity)?;
    let selected = self.active()?;
    let slot = self.slot()?;
    let state = self.slot_state_with_progress(slot, progress)?;
    if let Some(scope) = readback.as_deref_mut() {
        scope.nominate_active(&self.db, selected.0)?;
    }
    self.check_persisted_state_with_readback(
        selected.0,
        &state,
        progress,
        readback.as_deref_mut(),
    )?;
    crate::ancestry_index::validate_tip(&self.db, self.ancestry_context()?, selected.0)
        .map_err(Error::local_integrity)?;
    if self.state_backend == StateBackend::AuthenticatedV1 {
        native_authenticated::verify_history_with_readback(
            &self.db,
            &self.settings,
            selected.0,
            progress,
            Some(&self.authenticated_arithmetic),
            readback.as_deref_mut(),
        )?;
    }
    ensure(
        self.active()? == selected && self.slot()? == slot,
        "GENERATION",
    )
    .map_err(Error::local_integrity)?;
    if let Some(scope) = readback {
        scope.validate_consumed(&self.db)?;
    }
    Ok(())

fn slot_state_with_progress(
    &self,
    slot: u64,
    progress: &mut dyn FnMut() -> Result<()>,
) -> Result<State> {
    progress()?;
    // Validate stored dimensions before copying a cell into Rust. SQL types
    // are retained: TEXT is not a value BLOB, and a BLOB is not a key TEXT.
    let mut stmt = self.db.prepare(
        "SELECT CASE WHEN typeof(key)='text' THEN CAST(substr(CAST(key AS BLOB),1,161) AS TEXT) ELSE key END,
         CASE WHEN typeof(value)='blob' THEN substr(value,1,4097) ELSE value END,
         length(CAST(key AS BLOB)),length(CAST(value AS BLOB))
         FROM kv WHERE slot=? ORDER BY kv.key",
    ).map_err(|error| Error::from(error).local_integrity())?;
    let mut rows = stmt
        .query([slot])
        .map_err(|error| Error::from(error).local_integrity())?;
    let mut state = State::new();
    let mut canonical_bytes = Vec::new();
    while let Some(row) = rows
        .next()
        .map_err(|error| Error::from(error).local_integrity())?
    {
        if state.len().is_multiple_of(256) {
            progress()?;
        }
        let key: String = (|| -> Result<_> {
            let key_len: i64 = row.get(2)?;
            let value_len: i64 = row.get(3)?;
            ensure(
                state.len()
                    < if growth_profile_v2::enabled(&self.settings.app) {
                        growth_profile_v2::MAX_TOTAL_KEYS
                    } else {
                        65_536
                    }
                    && (0..=160).contains(&key_len)
                    && (0..=4096).contains(&value_len),
                "STATE_BYTES",
            )?;
            Ok(row.get(0)?)
        })()
        .map_err(Error::local_integrity)?;
        // The bounded SQL BLOB remains borrowed until this row advances.
        // Decoded State owns its data; no SQLite borrow escapes this scope.
        let cell = row
            .get_ref(1)
            .map_err(|error| Error::from(error).local_integrity())?;
        let bytes = cell.as_blob().map_err(|_| {
            Error::from(rusqlite::Error::InvalidColumnType(
                1,
                "value".into(),
                cell.data_type(),
            ))
            .local_integrity()
        })?;
        let value: Value = serde_json::from_slice(bytes)
            .map_err(|error| Error::from(error).local_integrity())?;
        canonical_bytes.clear();
        serde_json::to_writer(&mut canonical_bytes, &value)
            .map_err(|error| Error::from(error).local_integrity())?;
        ensure(canonical_bytes == bytes, "STATE_BYTES").map_err(Error::local_integrity)?;
        state.insert(key, value);
    }
    progress()?;
    Ok(state)

fn invalidate_commitment(&self) {
    *self.commitment_cache.borrow_mut() = None;
    self.historical_commitment_cache.borrow_mut().clear();
}
/// Local calculation observation only, never a state/confirmation authority.
pub fn derived_commitment_status(&self) -> DerivedCommitmentStatus {
    let cache = self.commitment_cache.borrow();
    DerivedCommitmentStatus {
        cache_root: cache.as_ref().map(|c| c.snapshot.root()),
        cache_keys: cache.as_ref().map_or(0, |c| c.snapshot.keys()),
        software_charge_bytes: cache
            .as_ref()
            .map_or(0, |c| c.snapshot.retained_charge_bytes()),
        last: self.commitment_observation.borrow().clone(),
    }
}
fn checked_commitment(
    &self,
    actual: &State,
    expected: Hash,
    prior: Option<&CheckedCommitment>,
) -> Result<PreparedCommitment> {
    let result = if growth_profile_v2::enabled(&self.settings.app) {
        pon_commitment::growth_reference_snapshot(actual, Some(expected), &self.settings.app)
    } else {
        pon_commitment::checked_snapshot_with_arithmetic(
            actual,
            expected,
            prior,
            CacheLimits::default(),
            &self.commitment_root_arithmetic,
        )
    };
    match result {
        Ok(prepared) => {
            if self.state_backend == StateBackend::AuthenticatedV1 {
                self.authenticated_arithmetic
                    .offer_root_material(&self.settings, prepared.snapshot.as_ref());
            }
            *self.commitment_observation.borrow_mut() = Some(prepared.observation.clone());
            Ok(prepared)
        }
        Err("COMMITMENT_ROOT") => {
            self.invalidate_commitment();
            Err(Error::from("ROOT").local_integrity())
        }
        Err(error) => Err(Error::from(error).local_integrity()),
    }

