/// Optional original sparse-tree arithmetic for a full-root fallback. Every use
/// still encodes and hashes the complete actual State; no root, partial update
/// or validity verdict can be installed. The fixed retention bound is separate
/// from canonical snapshot/workspace limits and is not a process RSS promise.
pub struct FullRootArithmetic(Mutex<StateRootArithmetic>);

const MAX_FULL_ROOT_ARITHMETIC_BYTES: usize = 2 * 1024 * 1024;

impl Default for FullRootArithmetic {
    fn default() -> Self {
        Self(Mutex::new(StateRootArithmetic::new(
            MAX_FULL_ROOT_ARITHMETIC_BYTES,
        )))
    }
}

impl FullRootArithmetic {
    fn root(&self, state: &State) -> Result<Hash> {
        // The guard covers only pure arithmetic, never SQL, worker joins or a
        // caller's progress/Host check. Contention and poison keep the original
        // full-root path; optional material cannot introduce a new refusal.
        let Ok(mut arithmetic) = self.0.try_lock() else {
            return pon_executor::root(state);
        };
        match pon_executor::root_with_arithmetic(state, &mut arithmetic) {
            Ok(root) => Ok(root),
            // Preserve the independent original grammar and exact error on any
            // arithmetic failure. No cancellation callback is caught here.
            Err(_) => pon_executor::root(state),
        }
    }
}

/// Optional bounded tree arithmetic over the complete actual State. This is a
/// root calculation, not a checked execution-parent or admission capability.
/// No root claim, partial update or caller-produced leaf hash can enter it.
/// Keep the independent original `root` above unchanged as the reference.
pub fn root_with_arithmetic(
    state: &State,
    arithmetic: &mut trnm_protocol::pon_wire::StateRootArithmetic,
) -> Result<Hash> {
    // The complete canonical pass must still precede every wire bound. In
    // particular, a late invalid number wins over an early oversized key.
    for value in state.values() {
        validate_canonical(value)?;
    }
    if state.len() > 65_536 {
        return Err("LIMIT");
    }
    let mut input = arithmetic.input_builder();
    for (key, value) in state {
        // Only a full current String/key equality can skip encoding. The
        // builder proves eligibility from its private original wire bytes;
        // every miss keeps the existing encoder and its actual allocations.
        if let Value::String(value) = value {
            if input
                .try_plain_json_string(key.as_bytes(), value)
                .map_err(|_| "LIMIT")?
            {
                continue;
            }
        }
        let bytes = canonical_after_validation(value)?;
        input
            .add_encoded(key.as_bytes(), &bytes)
            .map_err(|_| "LIMIT")?;
    }
    input.finish().map_err(|_| "LIMIT")

/// Consensus-profile selected root. The historical root function and every old
/// profile retain their complete grammar, error order and 65,536-key boundary.
pub fn root_for_config(state: &State, cfg: &Config) -> Result<Hash> {
    pq_accounts_v2::validate_state(state, cfg)?;
    if crate::growth_profile_v2::enabled(cfg) {
        Ok(crate::growth_profile_v2::commitment(state, cfg)?.id())
    } else {
        root(state)
    }
}

/// One optional mathematical entry. Its byte limit controls retention only;
/// refusing material never changes accepted inputs or the original state root.
/// The opaque type cannot be restored from serialized roots or hash claims.
pub struct StateRootArithmetic {
    max_retained_payload_bytes: usize,
    material: Option<Material>,
    observation: StateRootArithmeticObservation,
}

/// An operation-local complete input. Only actual bytes can add a leaf; no
/// caller can install a prehash or root. Dropping an unfinished or failed input
/// preserves the preceding complete material. Grammar checks that precede wire
/// limits remain the caller's responsibility, as for `root_from_entries`.
///
/// ```compile_fail
/// use trnm_protocol::pon_wire::StateRootArithmetic;
/// let mut arithmetic = StateRootArithmetic::new(1024);
/// let mut input = arithmetic.input_builder();
/// input.leaves.push(([0u8; 32], [0u8; 32]));
/// ```
pub struct StateRootInputBuilder<'a> {
    arithmetic: &'a mut StateRootArithmetic,
    leaves: Vec<(Hash, Hash)>,
    prior_strings_used: Vec<bool>,
    pending_strings: Vec<ExactString>,
    // Built only for a potentially retainable new string, never for an exact
    // current-key hit. Bounded by the original retained/pending entries and
    // discarded with this builder; it carries no retained budget.
    values: Option<BTreeMap<ValueIndex, Arc<PlainValue>>>,
    pending_budget: usize,
    observation: StateRootArithmeticObservation,
    failed: Option<WireError>,

fn finish_inputs(
    &mut self,
    mut leaves: Vec<(Hash, Hash)>,
    prior_strings_used: Vec<bool>,
    pending_strings: Vec<ExactString>,
    mut observation: StateRootArithmeticObservation,
) -> Result<Hash, WireError> {
    leaves.sort_unstable_by_key(|row| row.0);
    if leaves.windows(2).any(|pair| pair[0].0 == pair[1].0) {
        return Err(WireError::KeyCollision);
    }
    let count = usize::from(!leaves.is_empty())
        + leaves
            .windows(2)
            .filter(|pair| prefix(&pair[0].0) != prefix(&pair[1].0))
            .count();
    // The input hash vector has the same bounded transient size as the
    // original root. At most 4096 partition records can be retained. Boxed
    // slices prevent unused Vec capacity from escaping the retention charge.
    let tree_charge = leaves.len() * std::mem::size_of::<(Hash, Hash)>()
        + count * std::mem::size_of::<Partition>();
    if tree_charge > self.max_retained_payload_bytes {
        self.material = None;
        observation.retention_refused = true;
        self.observation = observation;
        return state_root_from_hashes(leaves);
    }

    let empty = state_empty_hashes();
    let mut partitions = Vec::with_capacity(count);
    let mut reused = 0;
    let mut start = 0;
    while start < leaves.len() {
        let id = prefix(&leaves[start].0);
        let end = start + leaves[start..].partition_point(|row| prefix(&row.0) == id);
        let prior = self.material.as_ref().and_then(|material| {
            let index = material
                .partitions
                .binary_search_by_key(&id, |partition| partition.prefix)
                .ok()?;
            let partition = &material.partitions[index];
            (material.leaves[partition.start..partition.end] == leaves[start..end])
                .then_some(partition.root)
        });
        let root = match prior {
            Some(root) => {
                reused += 1;
                root
            }
            None => subtree(&leaves[start..end], PARTITION_DEPTH, empty),
        };
        partitions.push(Partition {
            prefix: id,
            start,
            end,
            root,
        });
        start = end;
    }
    let root = partition_root(&partitions, 0, empty);

/// Try a complete current raw JSON string. A hit proves byte-for-byte
/// equality with a previously encoded unescaped ASCII string under this
/// exact key, then adds that row. A miss adds nothing: the caller must use
/// its original canonical encoder and `add_encoded`, with its original
/// grammar/error order. No caller-supplied eligibility flag is trusted.
pub fn try_plain_json_string(&mut self, key: &[u8], value: &str) -> Result<bool, WireError> {
    if let Some(error) = self.failed {
        return Err(error);
    }
    let hit =
        self.prior_string(key).and_then(|(index, prior)| {
            (&prior.value.bytes[1..prior.value.bytes.len() - 1] == value.as_bytes())
                .then_some((index, prior.hashes, prior.value.bytes.len()))
        });
    let Some((index, hashes, encoded_len)) = hit else {
        return Ok(false);
    };
    self.bounds(key, encoded_len)?;
    self.add_exact(index, hashes, true);
    Ok(true)
}

/// Add complete canonical/wire bytes. The original wire bounds precede
/// hashing; exact strings can avoid hashing only after full byte equality.
/// Other values use the original domains even when their lengths coincide.
pub fn add_encoded(&mut self, key: &[u8], value: &[u8]) -> Result<(), WireError> {
    self.bounds(key, value.len())?;
    let hit = self.prior_string(key).and_then(|(index, prior)| {
        (prior.value.bytes.as_ref() == value).then_some((index, prior.hashes))
    });
    if let Some((index, hashes)) = hit {
        self.add_exact(index, hashes, false);
        return Ok(());
    }
    let hashes = (
        hash(b"state-key", &[key]),
        hash(b"state-leaf", &[key, value]),
    );
    self.leaves.push(hashes);
    self.observation.input_keys += 1;
    self.observation.leaf_hashes_computed += 1;
    self.retain_string(key, value, hashes);
    Ok(())

let mut after = settings.genesis();
last_successful_after = Some(after);
let mut count = 0;
let mut trials = 0;
let mut solve_ns = 0;
while after != tip {
    sync_stage = "history-rpc";
    last_requested_after = Some(after);
    advertised_page_complete = None;
    import_call_elapsed_ns = None;
    let call_started = Instant::now();
    let reply_result = public_v2::call_public_protected_v2(
        address,
        &Request::History {
            tip: hex::encode(tip),
            after: hex::encode(after),
        },
        &settings,
        &server_pin,
        &caller,
        policy,
    );
    history_rpc_elapsed_ns = Some(call_started.elapsed().as_nanos());
    let reply = reply_result?;
    sync_stage = "history-response-check";
    if !reply.ok {
        return Err(format!("PUBLIC_HISTORY_REFUSED:{}", reply.value).into());
    }
    trials += reply.solve_trials;
    solve_ns += reply.solve_elapsed_ns;
    sync_stage = "decode-page";
    let page: Page = serde_json::from_value(reply.value)?;
    advertised_page_complete = Some(page.complete);
    sync_stage = "page-count-check";
    if page.packets.len() != 1 {
        return Err("PAGE_COUNT".into());
    }
    sync_stage = "first-packet-check";
    if count == 0
        && Packet::decode(&hex::decode(&page.packets[0]).map_err(codec)?)?.id()?
            != first.ok_or("FIRST")?
    {
        return Err("LONG_FIRST_PAGE".into());
    }
    sync_stage = "import-call-expression";
    let call_started = Instant::now();
    let import_result = ingress::receive_public_page_from(
        &mut confirmer,
        address,
        page,
        tip,
        after,
        ingress::now()?,
    );
    import_call_elapsed_ns = Some(call_started.elapsed().as_nanos());
    after = import_result?;
    count += 1;
    completed_import_calls = count;
    last_successful_after = Some(after);
    sync_stage = "partial-active-check";
    if count < BLOCKS && confirmer.active()?.0 != settings.genesis() {
        return Err("PARTIAL_SYNC_ACTIVATED".into());
    }
